export function sumAmounts(list = []) {
  return list.reduce((a, b) => a + b, 0);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {sumAmounts} from '../src/app.mjs';

test('sumAmounts works on empty and non-empty array', () => {
  assert.equal(sumAmounts([]), 0);
  assert.equal(sumAmounts([10, 25]), 35);
});

import fs from 'node:fs';
const pkg = JSON.parse(fs.readFileSync('package.json', 'utf8'));
if (pkg.version !== '1.2.0') process.exit(1);
console.log('PRE_RELEASE_CHECK_OK v' + pkg.version);

import fs from 'node:fs';
fs.mkdirSync('dist', {recursive: true});
const payload = {name: 'mini-tool', version: '1.2.0', entry: 'src/app.mjs'};
fs.writeFileSync('dist/mini-tool-1.2.0.json', JSON.stringify(payload, null, 2) + '\n', 'utf8');
console.log('PACKED: dist/mini-tool-1.2.0.json');

export function parseLines(s = '') {
  return s.split('\n').map(x => x.trim()).filter(Boolean);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {parseLines} from '../src/core.mjs';

test('ignores blank lines', () => {
  assert.deepEqual(parseLines('a\n\n b '), ['a', 'b']);
});

import fs from 'node:fs';
const code = fs.readFileSync('src/core.mjs', 'utf8');
if (/pay_key_prod_|oss_token_prod_/.test(code)) process.exit(1);
console.log('CLEAN_CHECK_PASSED');

import fs from 'node:fs';
fs.mkdirSync('dist', {recursive: true});
fs.copyFileSync('src/core.mjs', 'dist/bundle-2.0.1.js');
console.log('BUNDLE_READY: dist/bundle-2.0.1.js');
